import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
constexpr int ROWS_PER_BLOCK = 8;
constexpr int TILE_K = 1024; // must be divisible by 4
constexpr int SPLIT_K = 4;   // split large K dimension across blocks for better parallelism
__global__ void cute_matvec_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M, int K, int split_k)
{
    int block_row = blockIdx.x * ROWS_PER_BLOCK;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    // Determine this block's slice of the K dimension (split-K).
    int chunk = (K / split_k) & ~3; // multiple of 4 for float4 alignment
    if (chunk <= 0) chunk = 4;
    int k_start = blockIdx.y * chunk;
    if (k_start >= K) return;
    int k_end = (blockIdx.y == split_k - 1) ? K : min(K, k_start + chunk);
    int local_K = k_end - k_start;
    if (local_K <= 0) return;
    // Shared-memory tile of B, reused across ROWS_PER_BLOCK rows of A
    // to cut down redundant global memory reads of B (which is the
    // same vector reloaded for every output row).
    __shared__ float4 smB[TILE_K / 4];
    float sums[ROWS_PER_BLOCK];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; r++) sums[r] = 0.f;
    int K4 = local_K / 4;
    int tileK4 = TILE_K / 4;
    const float4* B4 = reinterpret_cast<const float4*>(B + k_start);
    int num_tiles = K4 / tileK4;
    for (int tile = 0; tile < num_tiles; tile++) {
        int base4 = tile * tileK4;
        for (int i = tid; i < tileK4; i += nthreads) {
            smB[i] = B4[base4 + i];
        }
        __syncthreads();
        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; r++) {
            int m = block_row + r;
            if (m < M) {
                const float4* A4 = reinterpret_cast<const float4*>(A + (size_t)m * (size_t)K + k_start);
                float local = 0.f;
                for (int i = tid; i < tileK4; i += nthreads) {
                    float4 a = A4[base4 + i];
                    float4 b = smB[i];
                    local += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                }
                sums[r] += local;
            }
        }
        __syncthreads();
    }
    int rem4 = K4 - num_tiles * tileK4;
    if (rem4 > 0) {
        int base4 = num_tiles * tileK4;
        for (int i = tid; i < rem4; i += nthreads) {
            smB[i] = B4[base4 + i];
        }
        __syncthreads();
        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; r++) {
            int m = block_row + r;
            if (m < M) {
                const float4* A4 = reinterpret_cast<const float4*>(A + (size_t)m * (size_t)K + k_start);
                float local = 0.f;
                for (int i = tid; i < rem4; i += nthreads) {
                    float4 a = A4[base4 + i];
                    float4 b = smB[i];
                    local += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                }
                sums[r] += local;
            }
        }
        __syncthreads();
    }
    // Scalar remainder for local_K not divisible by 4
    int rem_start = K4 * 4;
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; r++) {
        int m = block_row + r;
        if (m < M) {
            float local = 0.f;
            for (int i = rem_start + tid; i < local_K; i += nthreads) {
                local += A[(size_t)m * (size_t)K + k_start + i] * B[k_start + i];
            }
            sums[r] += local;
        }
    }
    // Warp-level + block-level reduction per row
    __shared__ float warp_sums[ROWS_PER_BLOCK][32];
    int lane = tid & 31;
    int warp_id = tid >> 5;
    int nwarps = (nthreads + 31) >> 5;
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; r++) {
        float sum = sums[r];
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        if (lane == 0) warp_sums[r][warp_id] = sum;
    }
    __syncthreads();
    if (warp_id == 0) {
        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; r++) {
            int m = block_row + r;
            float total = (lane < nwarps) ? warp_sums[r][lane] : 0.f;
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                total += __shfl_down_sync(0xffffffff, total, offset);
            }
            if (lane == 0 && m < M) {
                atomicAdd(&C[m], total);
            }
        }
    }
}
torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    int M = (int)A.size(0);
    int K = (int)A.size(1);
    TORCH_CHECK((int)B.size(0) == K, "B.size(0) must equal A.size(1)");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    // C must start at zero because split-K partial sums are accumulated via atomicAdd.
    auto C = torch::zeros({M, 1}, A.options());
    int threads = 256;
    int split_k = SPLIT_K;
    dim3 block(threads);
    dim3 grid((M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK, split_k);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_matvec_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), M, K, split_k);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE matvec launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix-vector multiplication (C = A * B)
    using a custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K).cuda()
    B = torch.rand(K, 1).cuda()
    return [A, B]


def get_init_inputs():
    return []

